edits.after:
static int smc_switch_to_fallback(struct smc_sock *smc, int reason_code)
{
	int rc = 0;

	/* The clcsock_release_lock is not needed here because the caller usually holds
	 * lock_sock/sk_lock, which prevents smc_release() from running (which is the
	 * only path that releases clcsock).
	 */
	if (!smc->clcsock) {
		rc = -EBADF;
		goto out;
	}

	smc->use_fallback = true;

